end
if CD.ice>0 then
local GD=bb.rogueShare(Bje[2141])
DD=DD*(GD+(1-GD)/(1-CD.ice+CD.ice/gb.modFactor(Bje[2547])))
end
if CD.fly>0 then
DD=DD*(1-CD.fly*0.5)
end
if CD.noCC then
DD=DD*0.95
end
if CD.shroud then
DD=DD*0.9
end
if CD.zap then
DD=DD*0.85
end
return DD/mb.weatherK(BD)
end
