ab.FUSE_RANK={Rare=1,Epic=2,Legendary=3}
function ab.xpFodder(Web)
local Xeb=N.session()
local Yeb=ab.FUSE_RANK[O.fuseXpRarity]or 2
local Zeb={[Web.uuid]=true,[O.evolveUnit]=true}
for _eb,afb in ipairs(V.equipped())do
Zeb[afb.uuid]=true
end
for bfb,cfb in ipairs(P.savedTeam or{})do
Zeb[cfb]=true
end
for dfb,efb in ipairs(P.train and P.train.on and P.train.on.base or{})do
Zeb[efb]=true
end
local ffb,gfb={},0
for hfb,ifb in pairs(Xeb.profile_data.collection.owned_units)do
local jfb=N.Units[ifb.unit_id]
local kfb=jfb and ab.FUSE_RANK[jfb.rarity]
if kfb and kfb<=Yeb and not Zeb[hfb]then
local lfb=Xeb.collection:get_unit_by_uuid(hfb)or ifb
if not(ifb._locked or lfb._locked)and not(ifb._equipped_relic or lfb._equipped_relic)then
local mfb,nfb=pcall(N.USC.calculate_xp_gain_from_fuse,Web,{lfb},Xeb)
nfb=mfb and tonumber(nfb)or 0
if nfb>0 then
table.insert(ffb,{uuid=hfb,id=ifb.unit_id,xp=nfb,rarity=jfb.rarity})
gfb=gfb+nfb
end
end
end
end
table.sort(ffb,function(ofb,pfb)
if ofb.xp~=pfb.xp then
return ofb.xp<pfb.xp
end
return ofb.uuid<pfb.uuid
end)
local qfb=math.max(0,kb.xpFor(Web.unit_id,kb.cap(Web))-(tonumber(Web.xp)or 0))
local rfb,sfb={},0
for tfb,ufb in ipairs(ffb)do
if sfb>=qfb then
break
end
table.insert(rfb,ufb)
sfb=sfb+ufb.xp
end
return rfb,sfb,qfb,gfb
end
