function ab.relicClash(bvb)
local cvb=N.session()
local dvb={}
for evb,fvb in ipairs(P.savedTeam or{})do
dvb[fvb]=true
end
local gvb={}
for hvb,ivb in ipairs(bvb)do
local jvb=cvb.collection:get_unit_by_uuid(ivb)
local kvb=jvb and jvb._equipped_relic and cvb.inventory:get_item_by_uuid(jvb._equipped_relic)
if kvb and kvb.item_id and(N.Items[kvb.item_id]or{}).unique_equip then
table.insert(gvb,{uuid=ivb,u=jvb,kind=kvb.item_id,relic=jvb._equipped_relic,k=(dvb[ivb]and 1e12 or 0)+kb.score(jvb)})
end
end
table.sort(gvb,function(lvb,mvb)
if lvb.k~=mvb.k then
return lvb.k>mvb.k
end
return lvb.uuid<mvb.uuid
end)
local nvb={}
for ovb,pvb in ipairs(gvb)do
if nvb[pvb.kind]then
local qvb=(N.Items[pvb.kind]or{}).name or pvb.kind
local rvb,svb=F.request(Bje[3511],Bje[3028],pvb.relic)
local tvb=U.now()
while U.now()-tvb<3 and pvb.u._equipped_relic==pvb.relic do
task.wait(0.25)
end
if pvb.u._equipped_relic~=pvb.relic then
P.relicOff[pvb.uuid]=pvb.relic
F.log(1,Bje[3053],string.format(Bje[3512],V.name(pvb.u.unit_id),qvb,V.name(nvb[pvb.kind])))
else
F.log(1,Bje[3053],string.format(Bje[3513],V.name(pvb.u.unit_id),qvb,tostring(svb)))
end
else
nvb[pvb.kind]=pvb.u.unit_id
end
end
end
