local Evb=U.now()
while U.now()-Evb<4 and kb.slotOf(Avb.uuid)do
task.wait(0.25)
end
end
F.request(Bje[3511],Bje[2535],wvb,{unit_uuid=vvb})
local Fvb=U.now()
while U.now()-Fvb<3 and xvb._equipped_relic~=wvb do
