function ab.equipTeam(Gvb,Hvb)
local Ivb={}
for Jvb,Kvb in ipairs(V.equipped())do
Ivb[Kvb.uuid]=true
end
if not P.savedTeam then
local Lvb={}
for Mvb,Nvb in ipairs(V.equipped())do
table.insert(Lvb,Nvb.uuid)
end
P.savedTeam=Lvb
end
local Ovb,Pvb=pcall(ab.relicClash,Gvb)
if not Ovb then
F.log(1,Bje[2394],Bje[3516]..tostring(Pvb))
end
local Qvb={}
for Rvb,Svb in ipairs(Gvb)do
Qvb[Svb]=true
end
local Tvb,Uvb=false,{}
for Vvb=1,4 do
for Wvb in pairs(Ivb)do
if not Qvb[Wvb]then
local Xvb,Yvb=F.request(Bje[2603],Bje[2604],Wvb)
table.insert(Uvb,string.format(Bje[3517],V.name((N.session().collection:get_unit_by_uuid(Wvb)or{}).unit_id or Bje[2243]),tostring(Yvb)))
task.wait(0.8)
end
end
for Zvb,_vb in ipairs(Gvb)do
if not Ivb[_vb]then
local awb
if Vvb>2 then
local bwb={}
for cwb,dwb in ipairs(V.equipped())do
bwb[dwb.slot]=true
end
for ewb=1,6 do
if not bwb[ewb]then
awb=ewb
break
end
end
end
local fwb,gwb
if awb then
fwb,gwb=F.request(Bje[3051],Bje[3052],_vb,awb)
else
fwb,gwb=F.request(Bje[3051],Bje[3052],_vb)
end
table.insert(Uvb,string.format(Bje[3518],V.name((N.session().collection:get_unit_by_uuid(_vb)or{}).unit_id or Bje[2243]),awb and(Bje[3519]..awb)or Bje[929],tostring(fwb),tostring(gwb)))
task.wait(0.8)
end
end
local hwb=U.now()
while U.now()-hwb<3 and not ib.same(ib.team(),Gvb)do
task.wait(0.25)
end
Tvb=ib.same(ib.team(),Gvb)
if Tvb then
break
end
Ivb={}
for iwb,jwb in ipairs(V.equipped())do
Ivb[jwb.uuid]=true
end
end
W._sigAt=nil
if Tvb then
F.log(1,Bje[3053],Bje[3520].. #Gvb..Bje[3521]..tostring(Hvb))
else
local kwb={}
for lwb,mwb in ipairs(V.equipped())do
table.insert(kwb,V.name(mwb.id))
end
F.log(1,Bje[3053],Bje[3522]..tostring(Hvb)..Bje[3523]..table.concat(kwb,Bje[2120])..Bje[3524]..table.concat(Uvb,Bje[2383]))
if not ab.refilling and#V.equipped()<6 then
ab.refilling=true
local nwb,owb={},{}
for pwb,qwb in ipairs(V.equipped())do
owb[qwb.uuid]=true
end
for rwb,swb in ipairs(P.savedTeam or{})do
if not owb[swb]and N.session().collection:get_unit_by_uuid(swb)then
table.insert(nwb,swb)
end
end
local twb=0
for uwb,vwb in ipairs(nwb)do
if#V.equipped()>=6 then
break
end
F.request(Bje[3051],Bje[3052],vwb)
task.wait(0.8)
local wwb=U.now()
while U.now()-wwb<3 and#V.equipped()<math.min(6,twb+1+(6- #nwb))do
task.wait(0.25)
end
for xwb,ywb in ipairs(V.equipped())do
if ywb.uuid==vwb then
twb=twb+1
end
end
end
local zwb={}
for Awb,Bwb in ipairs(V.equipped())do
table.insert(zwb,V.name(Bwb.id))
end
F.log(1,Bje[3053],string.format(Bje[3525],twb,table.concat(zwb,Bje[2120])))
W._sigAt=nil
ab.refilling=nil
end
end
F.saveSoon()
return Tvb
end
function ab.ownSwap()
