ab.LAB={EVERY=3,KINDS={story=true,raid=true,infinite=true},MIN_EVIDENCE=5,AGAIN=3600}
function ab.unitEvidence(Vwb)
local Wwb=P.learn[Vwb]
local Xwb=Wwb and tonumber(Wwb.n)or 0
local Ywb=db.hive()
local Zwb=Ywb and type(Ywb.units)==Bje[2008]and Ywb.units[Vwb]
if type(Zwb)==Bje[2008]then
Xwb=Xwb+(tonumber(Zwb.matches)or 0)+(tonumber(Zwb.matches3)or 0)
end
return Xwb
end
function ab.unitLabSafe(_wb)
if O.unitLab==false or type(_wb)~=Bje[2008]or not ab.LAB.KINDS[_wb.kind]or _wb.first then
return false
end
if P.trial or(P.study and not P.study.done)or(type(P.testTeam)==Bje[2008]and(tonumber(P.testTeam.left)or 0)>0)or(P.train and P.train.on)or ab.partyRole()~=Bje[935]then
return false
end
local axb,bxb=pcall(ab.matchOn,_wb)
if axb and bxb then
return false
end
local cxb=type(P.unitLab)==Bje[2008]and P.unitLab or{}
if cxb.pauseKey==_wb.key and os.time()<(tonumber(cxb.pauseUntil)or 0)then
return false
end
local dxb=W.rec(_wb.key)
local exb,fxb=tonumber(dxb.runs)or 0,tonumber(dxb.wins)or 0
if _wb.kind==Bje[2027]then
local gxb,hxb=pcall(W.infDaily,N.prof(),_wb.level,W.infReach(_wb.key))
return exb>=3 and gxb and(tonumber(hxb)or 1)<=0
end
return exb>=5 and(tonumber(dxb.streak)or 0)==0 and fxb/exb>=0.9
end
function ab.unitLab(ixb)
if not ab.unitLabSafe(ixb)then
return
end
P.unitLab=type(P.unitLab)==Bje[2008]and P.unitLab or{}
local jxb=P.unitLab
jxb.tried=type(jxb.tried)==Bje[2008]and jxb.tried or{}
jxb.seen=(tonumber(jxb.seen)or 0)+1
if jxb.seen%ab.LAB.EVERY~=0 then
return
end
local kxb=N.session()
local lxb=V.equipped()
if not kxb or#lxb<2 then
return
end
local mxb={}
for nxb,oxb in ipairs(lxb)do
mxb[oxb.uuid]=true
mxb[oxb.id]=true
end
local pxb,qxb,rxb
for sxb,txb in pairs(kxb.profile_data.collection.owned_units)do
local uxb=txb.unit_id
if not mxb[sxb]and not mxb[uxb]and N.Units[uxb]and not V.isFarm(uxb)and not V.allyBuff(uxb)and os.time()-(tonumber(jxb.tried[uxb])or 0)>ab.LAB.AGAIN then
local vxb=ab.unitEvidence(uxb)
if vxb<ab.LAB.MIN_EVIDENCE then
local wxb=kxb.collection:get_unit_by_uuid(sxb)or txb
local xxb=kb.score(wxb)
if xxb>0 and(not pxb or vxb<qxb or(vxb==qxb and xxb>rxb))then
pxb,qxb,rxb={uuid=sxb,id=uxb,u=wxb},vxb,xxb
end
end
end
end
if not pxb then
return
end
local yxb,zxb
for Axb,Bxb in ipairs(lxb)do
if not V.isFarm(Bxb.id)and not V.allyBuff(Bxb.id)and Bxb.uuid~=O.evolveUnit then
local Cxb=kb.score(Bxb.u)
if not yxb or Cxb<zxb then
yxb,zxb=Bxb,Cxb
end
end
end
if not yxb then
return
end
jxb.tried[pxb.id]=os.time()
local Dxb=0
for Exb in pairs(jxb.tried)do
Dxb=Dxb+1
if Dxb>300 then
jxb.tried[Exb]=nil
end
end
local Fxb,Gxb=gb.levelFor(ixb)
if not Fxb then
return
end
local Hxb=gb.info(Fxb,ixb.key,Gxb,ixb.mod or W.ldMod(Fxb)or W.levelMod(ixb.level))
local Ixb={}
for Jxb,Kxb in ipairs(lxb)do
table.insert(Ixb,Kxb.uuid==yxb.uuid and pxb.u or Kxb.u)
end
local Lxb,Mxb=pcall(gb.run,Hxb,gb.teamFrom(Ixb,Hxb.map),{hpMul=1.1})
local Nxb=Lxb and type(Mxb)==Bje[2008]and(Mxb.won or(Hxb.infinite and(tonumber(Mxb.wave)or 0)>=0.8*W.infReach(ixb.key)))
if not Nxb then
F.log(2,Bje[3535],string.format(Bje[3536],V.name(pxb.id),ixb.label))
return
end
local Oxb={}
for Pxb,Qxb in ipairs(lxb)do
table.insert(Oxb,Qxb.uuid==yxb.uuid and pxb.uuid or Qxb.uuid)
end
if ab.equipTeam(Oxb,Bje[3537]..V.name(pxb.id))then
jxb.now={id=pxb.id,out=yxb.id,key=ixb.key,at=os.time(),ev=qxb}
F.log(1,Bje[3535],string.format(Bje[3538],V.name(pxb.id),V.name(yxb.id),ixb.label,qxb))
F.saveNow()
end
end
function ab.unitLabDone(Rxb)
