else
vyb,wyb=pcall(V.score,uyb)
end
wyb=vyb and wyb or 0
if not pyb or wyb>pyb then
oyb,pyb=tyb.uuid,wyb
end
end
end
end
if oyb then
table.insert(hyb,oyb)
end
end
if#hyb== #O.dailyTeam then
if P.train.on then
ib.home()
end
if not ib.same(ib.team(),hyb)then
ab.equipTeam(hyb,Bje[3549])
end
