end
F.log(1,Bje[3053],Bje[3550])
end
local xyb=P.savedTeam or ib.team()
local yyb={}
for zyb,Ayb in ipairs(xyb)do
local Byb=cyb.collection:get_unit_by_uuid(Ayb)
if Byb then
table.insert(yyb,Byb)
end
end
if#yyb==0 then
return
end
local Cyb=gb.sig(yyb)
local Dyb=P.simTeam[ayb.key]
if not(Dyb and Dyb.base==Cyb and os.time()-(tonumber(Dyb.at)or 0)<120)then
