end
end
local Gyb=P.simTeam[ayb.key]
local Hyb=Gyb and Gyb.base==Cyb and os.time()-(tonumber(Gyb.at)or 0)<120
local Iyb=(Hyb and Gyb.better and type(Gyb.uuids)==Bje[2008]and#Gyb.uuids>0)and Gyb.uuids or xyb
local Jyb=P.train.on
