function eb.upgradeGain(yBb,zBb,ABb,BBb,CBb,DBb)
local EBb,FBb=zBb[ABb],zBb[ABb+1]
local GBb=(EBb.cd>0 and EBb.damage/EBb.cd or 0)
local HBb=(FBb.cd>0 and FBb.damage/FBb.cd or 0)*V.aoe(FBb.atk,FBb.range)/math.max(0.3,V.aoe(EBb.atk,EBb.range))
local IBb=GBb>0 and yBb*(HBb/GBb-1)or(DBb or 0)
local JBb=zBb[ABb+2]
if JBb and ABb+1<zBb.max and JBb.cd>0 and FBb.cd>0 and GBb>0 then
local KBb=yBb*((JBb.damage/JBb.cd)/GBb-1)
local LBb=BBb+JBb.cost*CBb
if KBb/LBb>IBb/BBb then
IBb=IBb+(KBb/LBb*BBb-IBb)*0.5
end
end
local MBb=(FBb.range or 0)>(EBb.range or 0)and(1+((FBb.range-EBb.range)/math.max(1,EBb.range)))or 1
return math.max(0,IBb)*MBb
end
function eb.dpsFor(NBb,OBb)
if OBb<=0 then
return 0
end
local PBb={}
for QBb,RBb in ipairs(NBb)do
if not RBb.farm and RBb.gain>0 then
table.insert(PBb,RBb)
end
end
table.sort(PBb,function(SBb,TBb)
return SBb.gain/SBb.cost>TBb.gain/TBb.cost
end)
local UBb,VBb=0,0
for WBb,XBb in ipairs(PBb)do
if OBb<=0 then
break
end
VBb=XBb.gain/XBb.cost
local YBb=math.min(1,OBb/XBb.cost)
UBb=UBb+XBb.gain*YBb
OBb=OBb-XBb.cost*YBb
end
return UBb+math.max(0,OBb)*VBb*0.7
end
function eb.shieldDps(ZBb,_Bb,aCb,bCb,cCb,dCb,eCb)
if(bCb or 0)<=0 or(ZBb or 0)<=0 or(cCb or 0)<=0 then
return ZBb or 0
end
_Bb,aCb,dCb=math.max(0.3,_Bb or 2),math.max(1,aCb or 1),dCb or 1
local fCb=ZBb*dCb*_Bb/aCb
return cCb*aCb/((bCb/math.max(1,eCb or 1)+math.max(1,cCb/fCb))*_Bb)/dCb
end
function eb.shieldGain(gCb,hCb,iCb,jCb,kCb,lCb,mCb,nCb)
local oCb,pCb=V.attackInfo(hCb.atk,hCb.range),V.attackInfo(jCb.atk,jCb.range)
local qCb=eb.shieldDps(gCb,(tonumber(hCb.cd)or 2)*(mCb or 1),oCb.n,kCb,lCb,nCb,oCb.hits)
local rCb=eb.shieldDps(iCb,(tonumber(jCb.cd)or 2)*(mCb or 1),pCb.n,kCb,lCb,nCb,pCb.hits)
local sCb=math.max(0,((tonumber(jCb.range)or 0)-(tonumber(hCb.range)or 0))/math.max(1,tonumber(hCb.range)or 1))
return math.max(0,rCb-qCb)+qCb*sCb
end
function eb.shieldWork(tCb,uCb,vCb,wCb,xCb,yCb,zCb,ACb,BCb)
if(wCb or 0)<=0 then
return 0
end
local CCb=3*wCb*(xCb or 1)/math.max(1,yCb or 20)
if(vCb or 0)>=CCb then
return 0
end
return math.max(1,tCb or 1)*math.max(1,BCb or 1)/math.max(0.3,uCb or 2)*math.min(zCb or 0,ACb or 0)
end
function eb.holdGain(DCb,ECb,FCb,GCb)
if not DCb or(ECb or 0)<=0 then
return 0
end
local HCb,ICb=tonumber(DCb.stun)or 0,tonumber(DCb.slowTime)or 0
if HCb<=0 and ICb<=0 then
return 0
end
local JCb,KCb=HCb>0 and HCb or ICb,HCb>0 and 1 or(tonumber(DCb.slowPct)or 0.3)
local LCb=KCb*JCb/(JCb+(tonumber(DCb.ccCd)or 8))
local MCb=LCb/math.max(0.1,1-LCb)
