jb.LUCK_RESERVE=500
jb.MIN_WORTH=0.02
jb.TOP_WORTH=0.08
function jb.shop(ujc,vjc)
local wjc=jb.cleared(ujc)
local xjc=jb.res(ujc)
local yjc=1+0.1*(jb.items(ujc)._curse_shop or 0)
local zjc=jb.shopAhead(ujc)and math.ceil(jb.LUCK_RESERVE*yjc)or 0
local Ajc={}
local Bjc,Cjc={},0
for Djc,Ejc in ipairs(jb.offers(vjc and vjc.data))do
Ejc.cost=math.ceil(Ejc.cost*yjc)
table.insert(Bjc,tostring(jb.item(Ejc.id).name or Ejc.id))
if not Ejc.bought and not jb.isCurse(Ejc.id)then
Ejc.luck=tonumber(jb.item(Ejc.id).luck_increase)~=nil
Ejc.v=jb.itemValue(Ejc.id,ujc)
if not Ejc.luck and Ejc.v/math.max(1,Ejc.cost)<jb.MIN_WORTH then
Cjc=Cjc+1
elseif Ejc.v>0 and(Ejc.luck or wjc>=10 or Ejc.v/math.max(1,Ejc.cost)>=jb.TOP_WORTH)then
table.insert(Ajc,Ejc)
end
end
end
table.sort(Ajc,function(Fjc,Gjc)
if Fjc.luck~=Gjc.luck then
return Fjc.luck
end
return Fjc.v/math.max(1,Fjc.cost)>Gjc.v/math.max(1,Gjc.cost)
end)
local Hjc,Ijc,Jjc={},0,0
for Kjc,Ljc in ipairs(Ajc)do
if Ljc.cost<=xjc-(Ljc.luck and 0 or zjc)then
if jb.buy(Ljc)then
xjc=jb.res(jb.data())
table.insert(Hjc,string.format(Bje[3939],tostring(jb.item(Ljc.id).name or Ljc.id),Ljc.cost))
end
elseif Ljc.cost<=xjc then
Jjc=Jjc+1
else
Ijc=Ijc+1
end
end
jb.note(string.format(Bje[3940],wjc,#Bjc>0 and table.concat(Bjc,Bje[2120])or Bje[3941],#Hjc>0 and(Bje[3942]..table.concat(Hjc,Bje[2120]))or(wjc<10 and Bje[3943]or(Jjc>0 and Bje[3944]or Bje[3945])),xjc,Ijc>0 and string.format(Bje[3946],Ijc)or Bje[929],Jjc>0 and string.format(Bje[3947],Jjc,zjc)or Bje[929],Cjc>0 and string.format(Bje[3948],Cjc)or Bje[929]))
F.request(Bje[3949],Bje[3950])
end
function jb.shrine(Mjc,Njc)
