end
jb.note(string.format(Bje[3953],#Qjc>0 and table.concat(Qjc,Bje[2120])or Bje[3941],Yjc and Bje[3954]or(Rjc and(Bje[3955]..Rjc)or Bje[3956])))
end
function jb.wallet()
local Zjc=N.session()and N.session().profile_data or{}
local _jc=Zjc.inventory or{}
local akc={gems=tonumber(N.cur(Bje[2072]))or 0,gold=tonumber(N.cur(Bje[2074]))or 0,items={},units={},unique=0}
