function jb.walletDiff(gkc,hkc)
local ikc={}
if hkc.gems~=gkc.gems then
table.insert(ikc,string.format(Bje[3957],hkc.gems-gkc.gems))
end
if hkc.gold~=gkc.gold then
table.insert(ikc,string.format(Bje[3958],hkc.gold-gkc.gold))
end
for jkc,kkc in pairs(hkc.items)do
if kkc~=(gkc.items[jkc]or 0)then
table.insert(ikc,string.format(Bje[3959],kkc-(gkc.items[jkc]or 0),tostring(jkc)))
end
end
for lkc,mkc in pairs(hkc.units)do
if not gkc.units[lkc]then
table.insert(ikc,Bje[3960]..V.name(mkc))
end
end
if hkc.unique~=gkc.unique then
table.insert(ikc,string.format(Bje[3961],hkc.unique-gkc.unique))
end
return#ikc>0 and table.concat(ikc,Bje[2120])or Bje[3962]
end
function jb.openChests(nkc,okc)
local pkc,qkc,rkc=jb.res(nkc)
local skc=jb.lives(nkc)
local tkc=jb.cleared(nkc)
if not(okc or tkc>=jb.ROOMS or skc<=1)then
jb.note(string.format(Bje[3963],tkc,qkc,rkc,jb.luck(nkc)))
F.request(Bje[3949],Bje[3950])
return
end
local ukc,vkc,wkc=0,0,0
local xkc=tonumber(N.cur(Bje[2072]))or 0
local ykc=jb.wallet()
for zkc=1,qkc+rkc+4 do
local Akc,Bkc,Ckc=jb.res(jb.data())
if Bkc+Ckc<=0 or wkc>=2 then
break
end
local Dkc,Ekc
if Bkc>0 then
Dkc,Ekc=F.request(Bje[3964],Bje[3965])
else
Dkc,Ekc=F.request(Bje[3964],Bje[3965],true)
end
if Dkc and Ekc~=nil then
F.log(1,Bje[3933],Bje[3966]..(type(Ekc)==Bje[2008]and U.json(U.plain(Ekc)):sub(1,300)or tostring(Ekc)))
end
local Fkc=U.now()
while U.now()-Fkc<4 do
local Gkc,Hkc,Ikc=jb.res(jb.data())
if Hkc<Bkc or Ikc<Ckc then
break
end
task.wait(0.25)
end
local Jkc,Kkc,Lkc=jb.res(jb.data())
if Kkc<Bkc then
ukc=ukc+(Bkc-Kkc)
wkc=0
elseif Lkc<Ckc then
vkc=vkc+(Ckc-Lkc)
wkc=0
else
wkc=wkc+1
end
task.wait(1)
if Kkc<Bkc or Lkc<Ckc then
local Mkc=jb.wallet()
local Nkc=jb.walletDiff(ykc,Mkc)
F.log(1,Bje[3933],(Lkc<Ckc and Bje[3967]or Bje[3966])..Nkc)
P.dg.pay=P.dg.pay or{}
local Okc={}
for Pkc,Qkc in pairs(Mkc.items)do
if Qkc~=(ykc.items[Pkc]or 0)then
Okc[Pkc]=Qkc-(ykc.items[Pkc]or 0)
end
end
table.insert(P.dg.pay,{at=os.time(),rare=Lkc<Ckc,gems=Mkc.gems-ykc.gems,luck=jb.luck(nkc),paid=Nkc,items=Okc})
while#P.dg.pay>60 do
table.remove(P.dg.pay,1)
end
ykc=Mkc
end
end
jb.note(string.format(Bje[3968],ukc,vkc,okc and Bje[3969]or(skc<=1 and Bje[3970]or Bje[3971]),jb.luck(nkc),(tonumber(N.cur(Bje[2072]))or 0)-xkc))
local Rkc,Skc,Tkc=jb.res(jb.data())
if(okc or tkc>=jb.ROOMS)and Skc+Tkc>0 then
jb.note(string.format(Bje[3972],Skc,Tkc))
W.rec(Bje[2727]).restUntil=os.time()+1800
return Bje[3973]
end
if not okc then
F.request(Bje[3949],Bje[3950])
end
end
