local plc=jb.fx(llc,jb.roomCurse(klc.r))
local qlc={}
if mlc and type(P.savedTeam)==Bje[2008]and#P.savedTeam>0 then
local rlc=N.session()
for slc,tlc in ipairs(P.savedTeam)do
