end
F.status(Bje[3071],Bje[3989]..klc.d)
gb.memoOn()
local Alc=jb.ways(ylc)
local Blc=type(P.dg.styles)==Bje[2008]and P.dg.styles[tostring(klc.r._r)]or nil
local function Clc(Dlc,Elc)
local Flc=gb.sig(Dlc)
local Glc=type(P.dg.teams)==Bje[2008]and P.dg.teams[Flc]or{}
local Hlc=type(P.dg.lost)==Bje[2008]and P.dg.lost[tostring(klc.r._r)]and P.dg.lost[tostring(klc.r._r)][Flc]or 0
local Ilc=type(P.dg.bailed)==Bje[2008]and type(P.dg.bailed[tostring(klc.r._r)])==Bje[2008]and tonumber(P.dg.bailed[tostring(klc.r._r)][Flc])or 0
Hlc=Hlc+Ilc
