if klc.d>=13 then
Nlc=math.min(Nlc,1)
end
Nlc=Nlc-3*Hlc
local Olc=Blc and type(Blc.lost)==Bje[2008]and Blc.lost[Elc.style]or nil
if type(Olc)==Bje[2008]and Olc.sig==Flc then
Nlc=Nlc-3
end
return{score=Jlc+Nlc,wins=Jlc,atOne=Klc,reach=Llc,far=Mlc,lostHere=Hlc,left=Ilc,w=tonumber(Glc.w)or 0,l=tonumber(Glc.l)or 0,style=Elc.style}
