function bb.buildPath()
bb.samples={}
local Xoc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not Xoc then
return
end
for Yoc,Zoc in pairs(Xoc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[Yoc.Name])then
local _oc={}
for apc,bpc in ipairs(Zoc.points or{})do
table.insert(_oc,bpc.part.Position)
end
local cpc=0
for dpc=2,#_oc do
cpc=cpc+(_oc[dpc]-_oc[dpc-1]).Magnitude
end
local epc=0
for fpc=2,#_oc do
local gpc,hpc=_oc[fpc-1],_oc[fpc]
local ipc=(hpc-gpc).Magnitude
local jpc=math.max(1,math.floor(ipc/2))
for kpc=0,jpc-1 do
local lpc=gpc:Lerp(hpc,kpc/jpc)
table.insert(bb.samples,{pos=lpc,prog=(epc+ipc*kpc/jpc)/math.max(1,cpc),lane=Yoc.Name})
end
epc=epc+ipc
end
if _oc[#_oc]then
table.insert(bb.samples,{pos=_oc[#_oc],prog=1,lane=Yoc.Name})
end
end
end
pcall(bb.readHidden,Xoc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local mpc=tonumber(bb.ld and bb.ld._portal_lanes)
local npc=gb.laneList(bb.samples)
if mpc and mpc>=1 and npc and#npc>mpc then
bb.laneWant=mpc
end
bb.laneTotal=npc and#npc or 1
bb.countLanes()
end
function bb.readHidden(opc)
local ppc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(ppc)~=Bje[2008]or not next(ppc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local qpc
for rpc,spc in pairs(opc)do
if ppc[rpc.Name]and type(spc.points)==Bje[2008]and#spc.points>=2 then
local tpc={}
for upc,vpc in ipairs(spc.points)do
tpc[upc]=U.flat(vpc.part.Position)
end
local wpc={}
for xpc,ypc in ipairs(bb.samples)do
local zpc=tostring(ypc.lane)
wpc[zpc]=wpc[zpc]or{}
table.insert(wpc[zpc],ypc)
end
local Apc,Bpc
for Cpc,Dpc in pairs(wpc)do
local Epc=0
for Fpc=1,#tpc,math.max(1,math.floor(#tpc/20))do
local Gpc=math.huge
for Hpc,Ipc in ipairs(Dpc)do
local Jpc=(U.flat(Ipc.pos)-tpc[Fpc]).Magnitude
if Jpc<Gpc then
Gpc=Jpc
end
end
Epc=Epc+Gpc
end
if not Bpc or Epc<Bpc then
Apc,Bpc=Cpc,Epc
end
end
local Kpc,Lpc,Mpc,Npc,Opc,Ppc={},nil,nil,nil,0,0
for Qpc,Rpc in ipairs(tpc)do
local Spc,Tpc=nil,math.huge
for Upc,Vpc in ipairs(wpc[Apc])do
local Wpc=(U.flat(Vpc.pos)-Rpc).Magnitude
if Wpc<Tpc then
Tpc,Spc=Wpc,Vpc.prog
end
end
Ppc=math.max(Ppc,Tpc)
if Mpc then
local Xpc=Spc-Mpc
local Ypc=(Xpc>0.002 and 1)or(Xpc< -0.002 and-1)or Npc
if Npc and Ypc and Ypc~=Npc then
table.insert(Kpc,math.floor(Mpc*1000+0.5)/1000)
end
Npc,Opc=Ypc or Npc,Opc+math.abs(Xpc)
else
Lpc=Spc
end
Mpc=Spc
if Qpc%50==0 then
task.wait()
end
end
if Mpc and Ppc<=8 then
table.insert(Kpc,math.floor(Mpc*1000+0.5)/1000)
qpc=qpc or{}
qpc[rpc.Name]={from=math.floor((Lpc or 0)*1000+0.5)/1000,len=math.floor(Opc*1000+0.5)/1000,turns=Kpc,road=Apc}
end
end
end
if not qpc then
return
end
local Zpc=bb.ld.map
P.maps[Zpc]=P.maps[Zpc]or{}
local _pc=P.maps[Zpc].hidden
P.maps[Zpc].hidden=qpc
if type(_pc)~=Bje[2008]then
for aqc,bqc in pairs(qpc)do
F.log(1,Bje[2676],string.format(Bje[4061],aqc,bqc.len,tostring(bqc.road),math.floor((#bqc.turns-1)/2)))
end
F.saveSoon()
end
end
