function bb.portalLanes()
if not bb.laneWant or bb.laneCut then
return true
end
if bb.planning then
return false
end
local lqc,mqc={},0
for nqc,oqc in ipairs(workspace._UNITS:GetChildren())do
local pqc=oqc:FindFirstChild(Bje[2071])
if pqc and pqc:FindFirstChild(Bje[4062])and pqc.player.Value==nil and pqc:FindFirstChild(Bje[4063])and oqc:FindFirstChild(Bje[3261])then
local qqc=tostring(pqc.lane.Value)
if not lqc[qqc]then
lqc[qqc]=true
mqc=mqc+1
end
end
end
if mqc==0 then
if U.now()-(bb.startT or U.now())>45 then
bb.laneWant=nil
F.log(1,Bje[2676],Bje[4064])
return true
end
return false
end
bb.laneFirst=bb.laneFirst or U.now()
if mqc<bb.laneWant and U.now()-bb.laneFirst<bb.LANE_WAIT then
return false
end
local rqc,sqc={},{}
for tqc,uqc in ipairs(bb.samples)do
if lqc[tostring(uqc.lane)]then
table.insert(rqc,uqc)
end
end
if#rqc==0 then
bb.laneWant=nil
return true
end
for vqc in pairs(lqc)do
table.insert(sqc,vqc)
end
table.sort(sqc)
bb.samples,bb.laneCut=rqc,table.concat(sqc,Bje[2322])
bb.countLanes()
local wqc,xqc=pcall(bb.buildCandidates)
if not wqc then
F.log(1,Bje[2394],Bje[4065]..tostring(xqc))
end
F.log(1,Bje[2676],string.format(Bje[4066],bb.laneWant,bb.laneCut))
if bb.info and O.simSpots and not bb.joinedMid and not bb.random and not bb.infinite and not bb.trialId then
bb.planning=U.now()
task.spawn(function()
local yqc,zqc=pcall(bb.planSpots)
bb.planning=nil
if not yqc then
F.log(1,Bje[2394],Bje[4067]..tostring(zqc))
end
end)
end
return true
end
function bb.buildWaves()
local Aqc=bb.ld
local Bqc=Aqc and Aqc._dungeon and type(Aqc._override_waves)==Bje[2008]and Aqc._override_waves or nil
local Cqc=Aqc and N.Waves[(Bqc and Bqc.template)or Aqc.waves or Aqc.id]
local Dqc
if type(Cqc)==Bje[2008]then
Dqc=Cqc.override_waves or Cqc.waves
if not Dqc and Cqc.template and N.Waves[Cqc.template]then
Dqc=N.Waves[Cqc.template].waves or N.Waves[Cqc.template].override_waves
end
end
bb.waveList=U.list(Dqc)
bb.infinite=Aqc and(Aqc._gamemode==Bje[2027]or Aqc.infinite)and gb.unbound(Aqc)or false
if bb.infinite then
bb.waveList={}
bb.total=math.max(30,math.floor(W.infReach(bb.key)+0.5))
return
end
bb.total=(Aqc and type(Aqc._dungeon)==Bje[2008]and 15)or tonumber(Aqc and Aqc._override_infinite_bound_waves)or gb.boundEnd(Aqc,#bb.waveList,bb.key)or(#bb.waveList>0 and#bb.waveList)or 15
end
function bb.infExtend()
if bb.infinite and bb.wave()+5>bb.total then
bb.total=bb.wave()+10
end
end
function bb.infWave(Eqc)
bb.infWaveAt=bb.infWaveAt or{}
bb.infWaveAt[Eqc]=bb.infWaveAt[Eqc]or U.now()
bb.infExtend()
if O.trainLeave and not bb.stopping then
local Fqc,Gqc=pcall(bb.trainLeave,Eqc)
if not Fqc then
F.log(1,Bje[2394],Bje[4068]..tostring(Gqc))
end
end
if O.infiniteStop and not bb.stopping and ab.partyRole()~=Bje[3555]and bb.kind~=Bje[2463]then
local Hqc,Iqc=pcall(bb.infStop,Eqc)
if not Hqc then
F.log(1,Bje[2394],Bje[4069]..tostring(Iqc))
end
end
local Jqc=W.infTier(Eqc-1)
if Jqc<=0 or Jqc==bb.infTierSeen then
return
end
bb.infTierSeen=Jqc
task.delay(5,function()
if not F.alive then
return
end
local Kqc=N.prof()
local Lqc=Kqc and Kqc.daily_infinite_reward_claims and Kqc.daily_infinite_reward_claims[bb.ld.id]
local Mqc=type(Lqc)==Bje[2008]and(tonumber(Lqc.highest_claimed_wave)or 0)>=Jqc and os.time()-(tonumber(Lqc.highest_claim_time)or 0)<900
if Mqc then
P.infLive=true
end
F.log(1,Bje[2676],string.format(Bje[4070],Jqc,Mqc and Bje[4071]or Bje[4072]))
end)
end
function bb.infStop(Nqc)
local Oqc=0
for Pqc,Qqc in ipairs(U.list(N.GS.DAILY_INFINITE_REWARDS))do
Oqc=math.max(Oqc,tonumber(Qqc.wave)or 0)
end
if Oqc<=0 or Nqc<=Oqc+1 then
return
end
local Rqc=P.train.on
if bb.trainee and Rqc and Rqc.have+(Rqc.got or 0)+(bb.trainTk or 0)<Rqc.need then
return
end
if not ab.every(Bje[4073],60)then
return
end
local Sqc=W.rec(bb.key)
local Tqc=tonumber(Sqc.timed)or 0
local Uqc=W.INF_PAY
local Vqc
if Nqc>=(Uqc.cap+Uqc.less)/Uqc.per then
Vqc=0
else
local Wqc=bb.infWaveAt or{}
local Xqc,Yqc=Wqc[Nqc],Wqc[Nqc-5]
if Xqc and Yqc and Xqc>Yqc then
Vqc=Uqc.per*5/((Xqc-Yqc)/60)
end
if not Vqc then
Vqc=(Tqc>0 and(Sqc.sec or 0)>0)and math.max(0.5,(Sqc.gems or 0)/(Sqc.sec/60))or 2.5
end
end
local Zqc=pcall(W.pick)
local _qc
for arc,brc in ipairs(Zqc and W.lastScored or{})do
if brc.kind~=Bje[2027]and(not _qc or(brc.score or 0)>(_qc.score or 0))then
_qc=brc
end
end
if not _qc or(_qc.score or 0)<=Vqc then
return
end
bb.stopping=true
F.log(1,Bje[2676],string.format(Bje[4074],Nqc,Vqc,_qc.score,_qc.label))
bb.sellAll()
end
function bb.trainLeave(crc)
local drc=P.train.on
if not(bb.infinite and bb.trainee and drc)then
return
end
bb.trainCount()
local erc=drc.have+(drc.got or 0)+(bb.trainTk or 0)
if erc<drc.need then
return
end
local frc,grc,hrc=pcall(W.infDaily,N.prof(),bb.ld.id,(W.infReach(bb.key)))
if frc and(grc or 0)>0 and hrc>0 and crc<=hrc then
F.status(Bje[3225],string.format(Bje[4075],V.name(drc.id),drc.what,hrc))
return
end
bb.stopping=true
F.log(1,Bje[2676],string.format(Bje[4076],V.name(drc.id),drc.what,U.fmt(erc),U.fmt(drc.need),crc))
bb.sellAll()
end
