function bb.valid(jtc,ktc,ltc)
local mtc=N.PC.raycast(jtc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not mtc then
return nil
end
if not N.PC.is_valid_raycast_hit(mtc.Instance,ktc)then
return nil
end
local ntc=mtc.Position
if bb.blockedSpot(ntc)then
return nil
end
local otc=(tonumber(ktc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(otc*2,2.5,otc*2)
bb.probe.CFrame=CFrame.new(ntc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
local ptc=U.flat(ntc)
for qtc,rtc in ipairs(bb.mine or{})do
local stc=rtc:FindFirstChild(Bje[4097])
local ttc=stc and stc.Position or rtc:GetPivot().Position
local utc=stc and math.max(stc.Size.X,stc.Size.Z)/2 or 1.5
if(ptc-U.flat(ttc)).Magnitude<otc+utc then
return nil
end
end
if not ltc then
for vtc,wtc in ipairs(bb.blockers())do
if(ptc-wtc.p).Magnitude<otc+wtc.r then
return nil
end
end
end
return ntc
end
function bb.buildCandidates()
bb.cands={}
local xtc={}
for ytc=1,#bb.samples,3 do
local ztc=bb.samples[ytc]
local Atc=bb.samples[math.min(#bb.samples,ytc+1)]
local Btc=U.flat(Atc.pos-ztc.pos)
if Btc.Magnitude<0.01 then
Btc=Vector3 .new(1,0,0)
end
Btc=Btc.Unit
local Ctc=Vector3 .new(-Btc.Z,0,Btc.X)
for Dtc,Etc in ipairs({3,4.5,6,8,10.5,13.5,17})do
for Ftc,Gtc in ipairs({1,-1})do
local Htc=ztc.pos+Ctc*Etc*Gtc
local Itc=string.format(Bje[4094],math.floor(Htc.X/1.5),math.floor(Htc.Z/1.5))
if not xtc[Itc]then
xtc[Itc]=true
table.insert(bb.cands,Htc)
end
end
end
end
end
function bb.coverage(Jtc,Ktc)
local Ltc={}
for Mtc,Ntc in ipairs(Jtc)do
local Otc=Ntc._stats
if not V.isFarm(Otc.id.Value)and Otc:FindFirstChild(Bje[2260])then
table.insert(Ltc,{p=U.flat(Ntc:GetPivot().Position),r=Otc.range.Value*(V.SUMMONER[Otc.id.Value]and V.SUMMONER[Otc.id.Value].reach or 1),air=bb.canAir(Ntc)})
end
end
local Ptc,Qtc=0,0
if#Ltc>0 then
for Rtc,Stc in ipairs(bb.samples)do
if Stc.prog>Qtc then
local Ttc=U.flat(Stc.pos)
for Utc,Vtc in ipairs(Ltc)do
if(Ttc-Vtc.p).Magnitude<=Vtc.r then
if Stc.prog>Ptc then
Ptc=Stc.prog
end
if Vtc.air then
Qtc=Stc.prog
break
end
end
end
end
end
end
local Wtc,Xtc={},bb.laneCount
if Xtc and Xtc.n>=2 and#Ltc>0 then
local Ytc={}
for Ztc,_tc in ipairs(bb.samples)do
local auc=U.flat(_tc.pos)
for buc,cuc in ipairs(Ltc)do
if(auc-cuc.p).Magnitude<=cuc.r then
local duc=tostring(_tc.lane)
Ytc[duc]=(Ytc[duc]or 0)+1
if _tc.prog>(Wtc[duc]or 0)then
Wtc[duc]=_tc.prog
end
break
end
end
end
local euc,fuc={},0
for guc,huc in pairs(Xtc.by)do
euc[guc]=(Ytc[guc]or 0)/math.max(1,huc)
fuc=math.max(fuc,euc[guc])
end
bb.laneW={}
for iuc,juc in pairs(Xtc.by)do
bb.laneW[iuc]=(Xtc.avg/math.max(1,juc))*(1+1.5*(fuc>0 and(1-euc[iuc]/fuc)or 0))
end
bb.laneFrac=euc
else
bb.laneW,bb.laneFrac=nil,nil
end
local kuc,luc,muc
if#Ltc>0 then
for nuc,ouc in ipairs(Ktc)do
local puc=(bb.laneW and ouc.lane)and(Wtc[tostring(ouc.lane)]or 0)or Ptc
if ouc.hp>0 and ouc.prog>puc+0.02 and ouc.prog>(kuc or 0)then
kuc,muc=ouc.prog,bb.laneW and ouc.lane or nil
end
if ouc.hp>0 and ouc.fly and ouc.prog>Qtc+0.02 then
luc=true
end
end
end
local quc= #Ltc>0 and(bb.pressure or 0)>=Ptc-0.08
return{covEnd=Ptc,airEnd=Qtc,leak=kuc,leakLane=muc,covL=Wtc,airLeak=luc,push=quc,units= #Ltc}
end
function bb.needLastLine(ruc)
if V.isFarm(ruc.id)or V.allyBuff(ruc.id)or bb.fieldCount()<5 then
return false
end
local suc,tuc=0,0
for uuc,vuc in ipairs(bb.mine or{})do
local wuc=vuc._stats
if not V.isFarm(wuc.id.Value)and wuc:FindFirstChild(Bje[2260])then
local xuc,yuc=U.flat(vuc:GetPivot().Position),wuc.range.Value
for zuc,Auc in ipairs(bb.samples)do
if Auc.prog>=0.85 and(U.flat(Auc.pos)-xuc).Magnitude<=yuc then
suc=suc+1
if bb.canAir(vuc)then
tuc=tuc+1
end
break
end
end
end
end
return suc<2 or(tuc<1 and bb.flyMode()and bb.cardAir(ruc.id))
end
