local VHc=UHc and UHc[UHc.max]and tonumber(UHc[UHc.max].range)
return VHc or(N.Units[THc]and tonumber(N.Units[THc].range))or nil
end
function bb.studyMoves(WHc,XHc)
local YHc=V.rows(WHc.id)
local ZHc=V.range(WHc.e.u,YHc.max)*XHc
local _Hc=ZHc*ZHc
local aIc,bIc={},{}
local cIc,dIc=bb.hurtSamples(),bb.sandLine()
for eIc,fIc in ipairs(WHc.spots or{})do
local gIc,hIc,iIc,jIc,kIc=0,0,0,0,0
for lIc,mIc in ipairs(cIc)do
local nIc,oIc=mIc.pos.X-fIc.X,mIc.pos.Z-fIc.Z
if nIc*nIc+oIc*oIc<=_Hc then
iIc=iIc+1
local pIc=math.min(49,math.floor(mIc.prog*50))
if pIc<25 then
gIc=bit32 .bor(gIc,bit32 .lshift(1,pIc))
else
hIc=bit32 .bor(hIc,bit32 .lshift(1,pIc-25))
end
if mIc.prog-dIc<=0.3 then
jIc=jIc+1
elseif mIc.prog>=0.7 then
kIc=kIc+1
end
end
end
if iIc>0 then
local qIc=gIc..Bje[2143]..hIc
local rIc=aIc[qIc]
if not rIc then
rIc={p=fIc,lo=gIc,hi=hIc,n=iIc,early=jIc,late=kIc}
aIc[qIc]=rIc
table.insert(bIc,rIc)
elseif iIc>rIc.n then
rIc.p,rIc.n,rIc.early,rIc.late=fIc,iIc,jIc,kIc
end
end
if eIc%40==0 then
task.wait()
end
end
local sIc={}
for tIc,uIc in ipairs(bIc)do
local vIc=false
for wIc,xIc in ipairs(bIc)do
if tIc~=wIc and xIc.n>=uIc.n and bit32 .band(uIc.lo,xIc.lo)==uIc.lo and bit32 .band(uIc.hi,xIc.hi)==uIc.hi and(xIc.lo~=uIc.lo or xIc.hi~=uIc.hi or xIc.n>uIc.n)then
vIc=true
break
end
end
if not vIc then
table.insert(sIc,uIc)
end
if tIc%40==0 then
task.wait()
end
end
local yIc,zIc={},{}
local function AIc(BIc)
if BIc and not zIc[BIc]then
zIc[BIc]=true
table.insert(yIc,BIc)
end
end
table.sort(sIc,function(CIc,DIc)
return CIc.n>DIc.n
end)
for EIc=1,math.min(bb.STUDY_K,#sIc)do
AIc(sIc[EIc].p)
end
table.sort(sIc,function(FIc,GIc)
return FIc.early>GIc.early
end)
AIc(sIc[1]and sIc[1].p)
AIc(sIc[2]and sIc[2].p)
table.sort(sIc,function(HIc,IIc)
return HIc.late>IIc.late
end)
AIc(sIc[1]and sIc[1].p)
AIc(sIc[2]and sIc[2].p)
local JIc=0
for KIc,LIc in ipairs(bb.hiveSpots(bb.ld and bb.ld.map))do
if JIc>=bb.STUDY_SHARED then
break
end
local MIc=false
for NIc,OIc in ipairs(type(LIc.units)==Bje[2008]and LIc.units or{})do
local PIc=OIc==WHc.id and ZHc or((bb.baseRange(OIc)or 0)*XHc)
if OIc==WHc.id or(PIc>0 and math.abs(PIc-ZHc)<=0.3*ZHc)then
MIc=true
break
end
end
local QIc=MIc and tonumber(LIc.x)and tonumber(LIc.z)and bb.nearSpot(WHc.spots,tonumber(LIc.x),tonumber(LIc.z))or nil
if QIc and not zIc[QIc]then
AIc(QIc)
JIc=JIc+1
end
end
return yIc,#bIc,#sIc,JIc
end
function bb.studyRun(RIc)
local SIc=U.now()
while F.alive and not(bb.finished or bb.result)and(bb.planning or U.now()-SIc<20)do
task.wait(1)
end
local function TIc()
return F.alive and not(bb.finished or bb.result)and O.mapStudy~=false and F.where==Bje[2080]
end
if not TIc()then
return
end
local UIc,VIc,WIc=RIc.info,RIc.team,RIc.base
local XIc=UIc.timeLimit~=nil
local YIc=XIc and 1 or math.max(1,tonumber(RIc.hard)or 1)
local ZIc={YIc*0.95,YIc*1.05}
local _Ic=bb.bookFor(UIc)
local aJc={key=RIc.key,label=bb.label(),n=_Ic and tonumber(_Ic.n)or 0,run=0,timed=XIc,kills=UIc.killScore and true or nil,hp=YIc,at=os.time()}
bb.study=aJc
local bJc,cJc,dJc,eJc,fJc={},0,0,0,0
for gJc,hJc in ipairs(RIc.attackers)do
local iJc,jJc,kJc,lJc=bb.studyMoves(hJc,RIc.scale)
bJc[hJc.id]=iJc
cJc,dJc,eJc,fJc=cJc+ #(hJc.spots or{}),dJc+jJc,eJc+ #iJc,fJc+lJc
if not TIc()then
return
end
end
aJc.moves=eJc
F.log(1,Bje[2761],string.format(Bje[4232],aJc.label,cJc,dJc,eJc,fJc>0 and string.format(Bje[4233],fJc)or Bje[929]))
local mJc={}
local function nJc(oJc)
return{samples=bb.samples,cache=mJc,spots=oJc,style=WIc.style,list=WIc.list,hybridHill=WIc.hybridHill}
end
local function pJc(qJc)
local rJc=0
for sJc,tJc in pairs(qJc)do
local uJc=bb.spotRec(sJc,tJc)
if uJc then
rJc=rJc+(tonumber(uJc.wins)or 0)*200-((tonumber(uJc.runs)or 0)-(tonumber(uJc.wins)or 0))*1500
end
end
return rJc
end
local function vJc(wJc)
local xJc,yJc,zJc=0,0,0
for AJc,BJc in ipairs(ZIc)do
local CJc=os.clock()
local DJc=gb.runRaw(UIc,VIc,{hpMul=BJc,layout=nJc(wJc),bg=true})
xJc,yJc,zJc=xJc+gb.objective(DJc),yJc+(tonumber(DJc.kills)or 0),zJc+(tonumber(DJc.wave)or 0)
task.wait(math.clamp((os.clock()-CJc)*3,0.25,RIc.pauseMax or 1.5))
if not TIc()then
return nil
end
end
aJc.n,aJc.run=aJc.n+1,aJc.run+1
return xJc/ #ZIc*100+pJc(wJc),yJc/ #ZIc,zJc/ #ZIc
end
local function EJc(FJc)
local GJc={}
for HJc,IJc in pairs(FJc)do
GJc[HJc]=IJc
end
return GJc
end
local function JJc(KJc,LJc,MJc)
for NJc,OJc in pairs(KJc)do
if NJc~=LJc and(U.flat(OJc)-U.flat(MJc)).Magnitude<4.5 then
return true
end
end
return false
end
local PJc={spots=EJc(WIc.spots)}
PJc.s,PJc.kills,PJc.wave=vJc(PJc.spots)
if not PJc.s then
return bb.studyEnd(aJc,RIc,nil)
end
aJc.baseKills,aJc.baseWave=PJc.kills,PJc.wave
aJc.bestKills,aJc.bestWave=PJc.kills,PJc.wave
if _Ic and _Ic.aside==nil then
local QJc,RJc=EJc(PJc.spots),0
for SJc,TJc in ipairs(RIc.attackers)do
local UJc=_Ic.spots[TJc.id]
local VJc=type(UJc)==Bje[2008]and tonumber(UJc[1])and tonumber(UJc[3])and bb.nearSpot(TJc.spots,tonumber(UJc[1]),tonumber(UJc[3]))or nil
if VJc and VJc~=QJc[TJc.id]and not JJc(QJc,TJc.id,VJc)then
QJc[TJc.id]=VJc
RJc=RJc+1
end
end
if RJc>0 then
local WJc,XJc,YJc=vJc(QJc)
if not WJc then
return bb.studyEnd(aJc,RIc,PJc)
end
if WJc>PJc.s then
PJc={spots=QJc,s=WJc,kills=XJc,wave=YJc}
aJc.bestKills,aJc.bestWave=XJc,YJc
end
end
end
local ZJc,_Jc=U.now(),aJc.run
local function aKc(bKc)
if not(bKc.s and bKc.s>PJc.s+math.max(50,math.abs(PJc.s)*0.005))then
return false
end
PJc=bKc
aJc.bestKills,aJc.bestWave,aJc.better=bKc.kills,bKc.wave,(aJc.better or 0)+1
pcall(bb.bookSave,UIc,RIc,PJc,aJc)
return true
end
local function cKc()
if aJc.run-_Jc>=60 or U.now()-ZJc>240 then
ZJc,_Jc=U.now(),aJc.run
F.log(1,Bje[2761],bb.studyWords(aJc))
end
end
local dKc={PJc}
for eKc,fKc in ipairs(RIc.attackers)do
local gKc={}
for hKc,iKc in ipairs(dKc)do
table.insert(gKc,iKc)
for jKc,kKc in ipairs(bJc[fKc.id]or{})do
if kKc~=iKc.spots[fKc.id]and not JJc(iKc.spots,fKc.id,kKc)then
local lKc=EJc(iKc.spots)
lKc[fKc.id]=kKc
local mKc,nKc,oKc=vJc(lKc)
if not mKc then
return bb.studyEnd(aJc,RIc,PJc)
end
local pKc={spots=lKc,s=mKc,kills=nKc,wave=oKc}
table.insert(gKc,pKc)
aKc(pKc)
cKc()
end
end
end
table.sort(gKc,function(qKc,rKc)
return(qKc.s or-1e18)>(rKc.s or-1e18)
end)
dKc={}
for sKc=1,math.min(bb.STUDY_BEAM,#gKc)do
table.insert(dKc,gKc[sKc])
end
end
local tKc={}
for uKc,vKc in ipairs(RIc.attackers)do
if bJc[vKc.id]and#bJc[vKc.id]>0 then
table.insert(tKc,vKc.id)
end
end
while TIc()and#tKc>0 do
local wKc=EJc(PJc.spots)
for xKc=1,math.min(2,#tKc)do
local yKc=tKc[math.random(#tKc)]
local zKc=bJc[yKc]
local AKc=zKc[math.random(#zKc)]
if not JJc(wKc,yKc,AKc)then
wKc[yKc]=AKc
end
end
local BKc,CKc,DKc=vJc(wKc)
if not BKc then
break
end
aKc({spots=wKc,s=BKc,kills=CKc,wave=DKc})
cKc()
end
bb.studyEnd(aJc,RIc,PJc)
end
bb.STUDY_INF_WAIT=240
function bb.validOpen(EKc,FKc)
local GKc=N.PC.raycast(EKc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not GKc then
return nil
end
if not N.PC.is_valid_raycast_hit(GKc.Instance,FKc)then
return nil
end
local HKc=GKc.Position
if bb.blockedSpot(HKc)then
return nil
end
local IKc=(tonumber(FKc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(IKc*2,2.5,IKc*2)
bb.probe.CFrame=CFrame.new(HKc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return HKc
end
function bb.studyInfinite()
if O.mapStudy==false or not(bb.info and bb.infinite)or bb.kind==Bje[2463]then
return
end
local JKc=bb.info
local function KKc()
return not F.alive or bb.finished or bb.result or F.where~=Bje[2080]or O.mapStudy==false or bb.withOthers or bb.fastAlways
end
local LKc,MKc={},{}
for NKc,OKc in ipairs(bb.team or{})do
table.insert(LKc,OKc.u)
if not V.isFarm(OKc.id)and not V.allyBuff(OKc.id)and OKc.uuid~=bb.trainee and V.rows(OKc.id)then
local PKc,QKc=pcall(V.score,OKc.u,bb.mod)
table.insert(MKc,{e=OKc,id=OKc.id,sc=PKc and QKc or 0})
end
end
if#MKc==0 then
return
end
table.sort(MKc,function(RKc,SKc)
return RKc.sc>SKc.sc
end)
local function TKc()
local UKc,VKc={},0
for WKc,XKc in ipairs(MKc)do
for YKc,ZKc in ipairs(bb.mine or{})do
local _Kc=ZKc:FindFirstChild(Bje[2071])
local aLc=_Kc and _Kc:FindFirstChild(Bje[2384])
if aLc and aLc.Value==XKc.e.uuid and _Kc:FindFirstChild(Bje[2385])and _Kc.id.Value==XKc.id then
UKc[XKc.id]=ZKc:GetPivot().Position
VKc=VKc+1
break
end
end
end
return UKc,VKc
end
local bLc=U.now()
local cLc,dLc=TKc()
while dLc< #MKc and U.now()-bLc<bb.STUDY_INF_WAIT do
task.wait(5)
if KKc()then
return
end
cLc,dLc=TKc()
end
if dLc==0 or KKc()then
return
end
local eLc={}
local function fLc(gLc)
local hLc=gLc.hybrid_placement and not gLc.hill_unit
local iLc=hLc and bb.hybridHill
local jLc=((gLc.hill_unit or iLc)and Bje[2787]or(hLc and Bje[4169])or Bje[4170])..Bje[2143]..tostring(gLc.override_hitbox_radius or Bje[929])
if eLc[jLc]then
return eLc[jLc]
end
local kLc={}
local lLc=iLc and bb.hillData(gLc)or gLc
for mLc,nLc in ipairs(bb.cands or{})do
local oLc=bb.validOpen(nLc,lLc)
if oLc then
table.insert(kLc,oLc)
end
if mLc%40==0 then
task.wait()
end
end
eLc[jLc]=kLc
return kLc
end
local pLc={info=JKc,team=gb.teamFrom(LKc,JKc.map),key=bb.bookKey(JKc),hard=1,scale=tonumber(JKc.rangeScale)or 1,attackers={},pauseMax=4,inf=true}
local qLc={spots={},style=Bje[2945],hybridHill=bb.hybridHill and true or false}
for rLc,sLc in ipairs(MKc)do
local tLc=(gb.holds(sLc.id)and not V.killFed(sLc.id))and true or false
local uLc=tLc and{}or table.clone(fLc(sLc.e.data))
if KKc()then
return
end
local vLc=cLc[sLc.id]
if vLc then
local wLc=bb.nearSpot(uLc,vLc.X,vLc.Z)
if not wLc then
wLc=vLc
table.insert(uLc,vLc)
end
qLc.spots[sLc.id]=wLc
end
if#uLc>0 then
table.insert(pLc.attackers,{id=sLc.id,e=sLc.e,spots=uLc})
end
end
pLc.base=qLc
bb.studyPool=pLc
F.log(1,Bje[2761],string.format(Bje[4234],bb.label(),dLc))
bb.studyRun(pLc)
end
function bb.studyWords(xLc)
if type(xLc)~=Bje[2008]then
return Bje[929]
end
local function yLc(zLc,ALc)
return xLc.kills and string.format(Bje[4179],math.floor((tonumber(zLc)or 0)+0.5))or string.format(Bje[4235],tonumber(ALc)or 0,tonumber(xLc.hp)or 1)
end
return string.format(Bje[4236],tostring(xLc.label),tonumber(xLc.n)or 0,tonumber(xLc.run)or 0,yLc(xLc.bestKills,xLc.bestWave),yLc(xLc.baseKills,xLc.baseWave),(xLc.better or 0)>0 and Bje[4237]or Bje[929])
end
function bb.bookSave(BLc,CLc,DLc,ELc)
P.mapBook=type(P.mapBook)==Bje[2008]and P.mapBook or{}
local FLc={}
for GLc,HLc in pairs(DLc.spots or{})do
FLc[GLc]={math.floor(HLc.X*10+0.5)/10,math.floor(HLc.Y*10+0.5)/10,math.floor(HLc.Z*10+0.5)/10}
end
P.mapBook[CLc.key]={spots=FLc,style=CLc.base.style,hp=ELc.hp,n=ELc.n,kills=DLc.kills and math.floor(DLc.kills+0.5)or nil,wave=DLc.wave and math.floor(DLc.wave*10+0.5)/10 or nil,base=ELc.baseWave and math.floor(ELc.baseWave*10+0.5)/10 or nil,label=ELc.label,map=BLc.map,killScore=ELc.kills,at=os.time()}
local ILc={}
for JLc,KLc in pairs(P.mapBook)do
table.insert(ILc,{k=JLc,at=type(KLc)==Bje[2008]and tonumber(KLc.at)or 0})
end
if#ILc>bb.BOOK_MAX then
table.sort(ILc,function(LLc,MLc)
return LLc.at>MLc.at
end)
for NLc=bb.BOOK_MAX+1,#ILc do
P.mapBook[ILc[NLc].k]=nil
end
end
F.saveSoon()
end
function bb.studyEnd(OLc,PLc,QLc)
if type(OLc)~=Bje[2008]or OLc.ended then
return
end
OLc.ended=true
if QLc and PLc then
local RLc=bb.bookFor(PLc.info)
if RLc then
RLc.n=OLc.n
F.saveSoon()
elseif OLc.run>0 then
pcall(bb.bookSave,PLc.info,PLc,QLc,OLc)
end
end
if OLc.run>0 then
F.log(1,Bje[2761],bb.studyWords(OLc))
end
end
function bb.studyReport()
local SLc=bb.info and bb.bookFor(bb.info)
if not SLc then
return nil
end
local TLc={}
for ULc,VLc in pairs(SLc.spots)do
if type(VLc)==Bje[2008]then
TLc[ULc]={VLc[1],VLc[3]}
end
end
return{n=SLc.n,kills=SLc.kills,wave=SLc.wave,hp=SLc.hp,spots=TLc}
end
function bb.studyText()
if O.mapStudy==false then
return Bje[3074]
end
if F.where==Bje[2080]and type(bb.study)==Bje[2008]and not bb.study.ended then
return Bje[4238]..bb.studyWords(bb.study)
end
local WLc,XLc,YLc=0,nil,0
for ZLc,_Lc in pairs(type(P.mapBook)==Bje[2008]and P.mapBook or{})do
if type(_Lc)==Bje[2008]then
WLc=WLc+1
if(tonumber(_Lc.at)or 0)>YLc then
XLc,YLc=_Lc,tonumber(_Lc.at)or 0
end
end
end
if WLc==0 then
return Bje[4239]
end
return string.format(Bje[4240],WLc,tostring(XLc.label),tonumber(XLc.n)or 0,XLc.killScore and string.format(Bje[4179],tonumber(XLc.kills)or 0)or string.format(Bje[4241],tostring(XLc.wave)))
end
function bb.spotResult(aMc,bMc)
if not(bb.info and bb.info.timeLimit)then
for cMc,dMc in pairs(bb.layoutUsed or{})do
local eMc=bb.spotRec(cMc,dMc,true)
eMc.runs,eMc.wins=(tonumber(eMc.runs)or 0)+1,(tonumber(eMc.wins)or 0)+(aMc and 1 or 0)
end
end
local fMc,gMc=pcall(bb.labRecord,aMc,bMc)
if not fMc then
F.log(1,Bje[2394],Bje[4228]..tostring(gMc))
end
local hMc,iMc=pcall(bb.layoutResult,aMc,bMc)
if not hMc then
F.log(1,Bje[2394],Bje[4242]..tostring(iMc))
end
if not bb.infinite then
bb.styleRecord(aMc)
end
end
bb.LAYOUT_KEEP,bb.LAYOUT_CONTROL,bb.HIVE_ASIDE,bb.HIVE_LEAD,bb.HIVE_LEAD_MIN=8,2,3600,0.015,300
function bb.layoutRecFor(jMc,kMc)
local lMc=bb.bookKey(jMc)
P.layoutRec=type(P.layoutRec)==Bje[2008]and P.layoutRec or{}
local mMc=P.layoutRec[lMc]
if type(mMc)~=Bje[2008]then
if not kMc then
return nil
end
mMc={at=os.time()}
P.layoutRec[lMc]=mMc
if U.count(P.layoutRec)>80 then
local nMc,oMc
for pMc,qMc in pairs(P.layoutRec)do
local rMc=type(qMc)==Bje[2008]and tonumber(qMc.at)or 0
if not oMc or rMc<oMc then
nMc,oMc=pMc,rMc
end
end
P.layoutRec[nMc]=nil
end
end
return mMc
end
function bb.layoutAdd(sMc,tMc,uMc,vMc,wMc)
sMc.runs,sMc.wins=(tonumber(sMc.runs)or 0)+1,(tonumber(sMc.wins)or 0)+(tMc and 1 or 0)
sMc.sec,sMc.wave=type(sMc.sec)==Bje[2008]and sMc.sec or{},type(sMc.wave)==Bje[2008]and sMc.wave or{}
if tMc and tonumber(uMc)then
table.insert(sMc.sec,math.floor(uMc+0.5))
end
table.insert(sMc.wave,tonumber(vMc)or 0)
if tonumber(wMc)then
sMc.kills=type(sMc.kills)==Bje[2008]and sMc.kills or{}
table.insert(sMc.kills,math.floor(tonumber(wMc)))
while#sMc.kills>bb.LAYOUT_KEEP do
table.remove(sMc.kills,1)
end
end
while#sMc.sec>bb.LAYOUT_KEEP do
table.remove(sMc.sec,1)
end
while#sMc.wave>bb.LAYOUT_KEEP do
table.remove(sMc.wave,1)
end
end
function bb.layoutJudge(xMc,yMc,zMc,AMc)
local BMc,CMc=tonumber(xMc and xMc.runs)or 0,tonumber(yMc and yMc.runs)or 0
if BMc<1 or CMc<bb.LAYOUT_CONTROL then
return nil
end
