table.insert(dNc,{p=jNc,r=kNc})
else
for lNc,mNc in ipairs(eNc)do
if(U.flat(mNc.pos)-jNc).Magnitude<=kNc then
aNc,bNc=math.min(aNc,mNc.prog),math.max(bNc,mNc.prog)
end
end
end
end
end
if bNc<=aNc then
aNc,bNc=0.75,0.98
end
local nNc=(ZMc or cNc)+1
