local XVc=0
for YVc,ZVc in ipairs(bb.mine or{})do
local _Vc=ZVc._stats
local aWc=V.rows(_Vc.id.Value)
local bWc=aWc and aWc[math.min(_Vc.upgrade.Value,aWc.max)]
local cWc=bWc and bWc.atk and V.attackInfo(bWc.atk,bWc.range)
if cWc and((cWc.stun or 0)>0 or(cWc.slowTime or 0)>0)then
XVc=XVc+1
end
end
local dWc,eWc=gb.mask(bb.info.map,V.range(UVc.u,0)*(bb.info.rangeScale or 1)),0
for fWc=1,gb.BINS do
if dWc[fWc]then
eWc=eWc+1
end
end
local gWc=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
local hWc=(V.airFrom(UVc.id)==0)and 1 or(1-(1-N.FLY_GROUND)*math.min(1,bb.info.flyChance or 0))
return eb.holdGain(WVc,bb.teamDps or 0,eWc/(math.max(0.1,gWc)*gb.BINS)*hWc,XVc)
