function bb.buffGain(iWc)
local jWc=V.allyBuff(iWc.id)
if not jWc then
return 0
end
local kWc,lWc,mWc=bb.buffShort(jWc)
local nWc=V.stackCap(jWc.attack)
local oWc,pWc=pcall(V.range,iWc.u,0)
pWc=(oWc and tonumber(pWc)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local qWc=nWc and O.community and tonumber(jWc.time)and tonumber(mWc)
local function rWc(sWc,tWc)
local uWc=math.floor(sWc*jWc.time/math.max(1,mWc)+0.001)
return math.min(nWc,(1+tWc)^uWc-1)
end
local vWc=0
for wWc,xWc in ipairs(kWc)do
local yWc=0
for zWc,AWc in ipairs(kWc)do
if(AWc.pos-xWc.pos).Magnitude<=pWc then
local BWc=jWc.types[AWc.base]
local CWc=BWc*jWc.uptime
if qWc then
local DWc,EWc=rWc(AWc.n,BWc),AWc.n+1
while EWc<AWc.n+6 and rWc(EWc,BWc)<=DWc+0.001 do
EWc=EWc+1
end
CWc=math.max(0,(rWc(EWc,BWc)-DWc)/(EWc-AWc.n))
elseif nWc then
CWc=math.max(0,math.min(nWc,(AWc.n+1)*BWc*jWc.uptime)-math.min(nWc,AWc.n*BWc*jWc.uptime))
end
yWc=yWc+AWc.dps*CWc
end
end
vWc=math.max(vWc,yWc)
end
return vWc*(qWc and 1 or 0.7)
end
