local Hbd,Ibd=Abd.foes or{},Bbd.foes or{}
for Jbd,Kbd in pairs(Ibd)do
if Kbd.prog>=bb.BASE_END then
Fbd=Fbd+Kbd.hp
local Lbd=Hbd[Jbd]
if Lbd then
Gbd=Gbd+math.max(0,Lbd.hp-Kbd.hp)
end
end
end
