function db.modsOf()
local function ctd(dtd)
local etd
for ftd,gtd in pairs(type(dtd)==Bje[2008]and dtd or{})do
etd=etd or{}
etd[ftd]=type(gtd)==Bje[2009]and math.floor(gtd*1000+0.5)/1000 or gtd
end
return etd
end
local htd={}
if bb.mod then
htd.weak,htd.res,htd.strong=ctd(bb.mod.weak),ctd(bb.mod.res),ctd(bb.mod.strong)
end
htd.seed=bb.ld._is_daily_challenge and tonumber(bb.ld._challenge_uuid)or nil
local itd={}
for jtd,ktd in pairs(bb.info and bb.info.configs or{})do
local ltd=type(ktd)==Bje[2008]and N.Units[ktd.unit_id]
if type(ltd)==Bje[2008]then
local mtd=type(ltd.enemy_modifiers)==Bje[2008]and ltd.enemy_modifiers or{}
for ntd,otd in pairs(mtd)do
if otd then
itd[ntd]=(itd[ntd]or 0)+1
end
end
if not mtd.Flying and gb.flies(ltd)then
itd.Flying=(itd.Flying or 0)+1
end
end
end
if next(itd)then
htd.enemy=itd
end
for ptd,qtd in ipairs({Bje[3701],Bje[3702],Bje[2547]})do
local rtd=P.enemyMods[qtd]
local std=gb.modRead(rtd)
if std then
htd.measured=htd.measured or{}
htd.measured[qtd]={f=math.floor(std*1000+0.5)/1000,n= #rtd.r}
end
end
return next(htd)and htd or nil
